package user

import (
  "time"

  "gorm.io/gorm"
)

func CountChurned(db *gorm.DB, from, to time.Time) (int64, error) {
  var n int64
  err := db.Model(&User{}).
    Where("deleted_at >= ? AND deleted_at < ?", from, to).
    Count(&n).Error
  return n, err
}

