type User struct {
  ID        uint
  Email     string         `gorm:"uniqueIndex:idx_users_email_deleted"`
  Plan      string
  DeletedAt gorm.DeletedAt `gorm:"uniqueIndex:idx_users_email_deleted"`
}

func Restore(db *gorm.DB, email string) error {
  var u User
  err := db.Unscoped().
    Where("email = ? AND deleted_at IS NOT NULL", email).
    Order("deleted_at DESC").
    First(&u).Error
  if err != nil {
    return err
  }
  return db.Unscoped().Model(&u).Update("deleted_at", nil).Error
}
